&lt;li&gt;&lt;span class=&quot;___1cs5bdp f1w7gpdv f5p0z4x&quot;&gt;Familiarity&lt;/span&gt; &lt;span class=&quot;___1cs5bdp f1w7gpdv f5p0z4x&quot;&gt;with&lt;/span&gt; &lt;span class=&quot;___1cs5bdp f1w7gpdv f5p0z4x&quot;&gt;Viva&lt;/span&gt; &lt;span class=&quot;___1cs5bdp f1w7gpdv f5p0z4x&quot;&gt;Insights,&lt;/span&gt; &lt;span class=&quot;___1cs5bdp f1w7gpdv f5p0z4x&quot;&gt;Power&lt;/span&gt; &lt;span class=&quot;___1cs5bdp f1w7gpdv f5p0z4x&quot;&gt;BI&lt;/span&gt; &lt;span class=&quot;___1cs5bdp f1w7gpdv f5p0z4x&quot;&gt;and&lt;/span&gt; &lt;span class=&quot;___1cs5bdp f1w7gpdv f5p0z4x&quot;&gt;adoption&lt;/span&gt; &lt;span class=&quot;___xxxjie0 f1w7gpdv f1gqqdtu&quot;&gt;analytics.&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span class=&quot;___1cs5bdp f1w7gpdv f5p0z4x&quot;&gt;Background&lt;/span&gt; &lt;span class=&quot;___1cs5bdp f1w7gpdv f5p0z4x&quot;&gt;in&lt;/span&gt; &lt;span class=&quot;___1cs5bdp f1w7gpdv f5p0z4x&quot;&gt;finance,&lt;/span&gt; &lt;span class=&quot;___1cs5bdp f1w7gpdv f5p0z4x&quot;&gt;audit,&lt;/span&gt; &lt;span class=&quot;___1cs5bdp f1w7gpdv f5p0z4x&quot;&gt;controls&lt;/span&gt; &lt;span class=&quot;___1cs5bdp f1w7gpdv f5p0z4x&quot;&gt;or&lt;/span&gt; &lt;span class=&quot;___1cs5bdp f1w7gpdv f5p0z4x&quot;&gt;business&lt;/span&gt; &lt;span class=&quot;___1cs5bdp f1w7gpdv f5p0z4x&quot;&gt;performance&lt;/span&gt; &lt;span class=&quot;___xxxjie0 f1w7gpdv f1gqqdtu&quot;&gt;measurement.&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span class=&quot;___1cs5bdp f1w7gpdv f5p0z4x&quot;&gt;Experience&lt;/span&gt; &lt;span class=&quot;___1cs5bdp f1w7gpdv f5p0z4x&quot;&gt;working&lt;/span&gt; &lt;span class=&quot;___1cs5bdp f1w7gpdv f5p0z4x&quot;&gt;within&lt;/span&gt; &lt;span class=&quot;___1cs5bdp f1w7gpdv f5p0z4x&quot;&gt;media,&lt;/span&gt; &lt;span class=&quot;___1cs5bdp f1w7gpdv f5p0z4x&quot;&gt;advertising,&lt;/span&gt; &lt;span class=&quot;___1cs5bdp f1w7gpdv f5p0z4x&quot;&gt;marketing&lt;/span&gt; &lt;span class=&quot;___1cs5bdp f1w7gpdv f5p0z4x&quot;&gt;services&lt;/span&gt; &lt;span class=&quot;___1cs5bdp f1w7gpdv f5p0z4x&quot;&gt;or&lt;/span&gt; &lt;span class=&quot;___1cs5bdp f1w7gpdv f5p0z4x&quot;&gt;similarly&lt;/span&gt; &lt;span class=&quot;___1cs5bdp f1w7gpdv f5p0z4x&quot;&gt;complex&lt;/span&gt; &lt;span class=&quot;___1cs5bdp f1w7gpdv f5p0z4x&quot;&gt;global&lt;/span&gt; &lt;span class=&quot;___xxxjie0 f1w7gpdv f1gqqdtu&quot;&gt;businesses.&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;p&gt;&lt;span style=&quot;text-decoration: underline;&quot;&gt;&lt;strong&gt;Who you are:&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;You&#39;re open&lt;em&gt;:&lt;/em&gt; &lt;/strong&gt;We are inclusive and collaborative; we encourage the free exchange of ideas; we respect and celebrate diverse views. We are open-minded: to new ideas, new partnerships, new ways of working.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;You&#39;re optimistic&lt;em&gt;:&lt;/em&gt;&lt;/strong&gt; &lt;span id=&quot;628d56ad5d8a35dab853e65d9daa237c&quot; class=&quot;editor-module-hl-green-solid&quot;&gt;We believe&lt;/span&gt; in the power of creativity, technology and talent to create brighter futures or our people, our clients and our communities. We approach all that we do with conviction: to try the new and to seek the unexpected.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;You&#39;re extraordinary:&lt;/strong&gt; we are stronger together: through collaboration we achieve the amazing. We are creative leaders and pioneers of our industry; we provide extraordinary every day.&lt;/p&gt;
&lt;p&gt;&lt;span style=&quot;text-decoration: underline;&quot;&gt;&lt;strong&gt;What we&#39;ll give you:&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Passionate, inspired people&lt;/strong&gt; – We aim to create a culture in which people can do extraordinary work.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Scale and opportunity&lt;/strong&gt; – We offer the opportunity to create, influence and complete projects at a scale that is unparalleled in the industry.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Challenging and stimulating work&lt;/strong&gt; – Unique work and the opportunity to join a group of creative problem solvers. Are you up for the challenge?&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;p&gt;&lt;strong&gt;We believe the best work happens when we&#39;re together, fostering creativity, collaboration, and connection. That&#39;s why we’ve adopted a hybrid approach, with teams in the office around four days a week. If you require accommodations or flexibility, please discuss this with the hiring team during the interview process.&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;WPP is an equal opportunity employer and considers applicants for all positions without discrimination or regard to particular characteristics. We are committed to fostering a culture of respect in which everyone feels they belong and has the same opportunities to progress in their careers.&lt;/strong&gt;&lt;/p&gt;
&lt;h4&gt;&lt;strong&gt;Please read our Privacy Notice (&lt;a href=&quot;https://www.wpp.com/en/careers/wpp-privacy-policy-for-recruitment&quot;&gt;https://www.wpp.com/en/careers/wpp-privacy-policy-for-recruitment&lt;/a&gt;) for more information on how we process the information you provide.&lt;/strong&gt;&lt;/h4&gt;&lt;/div&gt;<p>Find more <a href="https://www.arbeitnow.co.uk/english-speaking-jobs">English Speaking Jobs in United Kingdom</a> on Arbeitnow</a>

&lt;div class=&quot;content-intro&quot;&gt;&lt;p&gt;&lt;strong&gt;WPP is the trusted growth partner for the world’s leading brands.&amp;nbsp;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;We unite cutting-edge media intelligence and data solutions, world-class creativity, next-generation production, transformative enterprise solutions and expert strategic counsel in a single company – powered by exceptional talent and our agentic marketing platform, WPP Open, to help our clients navigate change, capture opportunity and deliver transformational growth.&amp;nbsp;&lt;/strong&gt;&lt;br&gt;&lt;strong&gt;&amp;nbsp;&lt;/strong&gt;&lt;br&gt;&lt;strong&gt;We work with the world&#39;s most valuable brands and have global reach across 100+ markets, with deep local expertise.&lt;/strong&gt;&lt;br&gt;&lt;strong&gt;&amp;nbsp;&lt;/strong&gt;&lt;br&gt;&lt;strong&gt;Our people are the key to our success. We&#39;re committed to fostering a culture of creativity, belonging and continuous learning, attracting and developing the brightest talent, and providing exciting career opportunities that help our people grow.&amp;nbsp;&lt;/strong&gt;&lt;br&gt;&lt;strong&gt;&amp;nbsp;&lt;/strong&gt;&lt;br&gt;&lt;strong&gt;For more information, visit &lt;a href=&quot;https://eur02.safelinks.protection.outlook.com/?url=http%3A%2F%2Fwpp.com%2F&amp;amp;data=05%7C02%7CErica.Durr%40wpp.com%7C9bf4566a65bc46a48ac008de749116ea%7C150b5e663d884dee83f6ed149b727a00%7C0%7C0%7C639076363668176216%7CUnknown%7CTWFpbGZsb3d8eyJFbXB0eU1hcGkiOnRydWUsIlYiOiIwLjAuMDAwMCIsIlAiOiJXaW4zMiIsIkFOIjoiTWFpbCIsIldUIjoyfQ%3D%3D%7C0%7C%7C%7C&amp;amp;sdata=Q9juosud56XGLThSFZ1NpPZd6FXpJPxV74OeRZWoh%2B4%3D&amp;amp;reserved=0&quot; target=&quot;_blank&quot;&gt;WPP.com.&lt;/a&gt;&lt;/strong&gt;&lt;br&gt;&lt;strong&gt;&amp;nbsp;&lt;/strong&gt;&lt;/p&gt;&lt;/div&gt;&lt;p&gt;&lt;span style=&quot;text-decoration: underline; font-size: 10pt;&quot;&gt;&lt;strong&gt;Why we&#39;re hiring:&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW258627743 BCX8&quot;&gt;This role is crucial for driving revenue growth and &lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW258627743 BCX8&quot;&gt;optimising&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW258627743 BCX8&quot;&gt; pricing strategies &lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW258627743 BCX8&quot;&gt;for WPP and specifically WPP Open&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW258627743 BCX8&quot;&gt;. The Pricing &amp;amp; Commercial Strategy &lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW258627743 BCX8&quot;&gt;Director&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW258627743 BCX8&quot;&gt; will collaborate with deal support, product teams, operations, and enablement to develop and implement effective pricing models, support client negotiations, and ensure consistent application of pricing principles. This role requires an analytical mindset, excellent communication skills, and a deep understanding of the media and advertising landscape&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;span style=&quot;text-decoration: underline; font-size: 10pt;&quot;&gt;&lt;strong&gt;What you&#39;ll be doing:&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;WPP Open Pricing Strategy:&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;335557856&amp;quot;:16777215,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:210}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li style=&quot;font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-size: 10pt;&quot; data-contrast=&quot;auto&quot;&gt;Lead pricing projects to develop the WPP Open pricing strategy for self service.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Conduct market research and competitive analysis to identify pricing trends and opportunities.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;335557856&amp;quot;:16777215,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:0}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Develop and maintain pricing models and tools to support pricing decisions.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;335557856&amp;quot;:16777215,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:0}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Use data-driven insights to inform revisions to pricing models and approaches&lt;/span&gt;&lt;/span&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;335557856&amp;quot;:16777215,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:0}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Sales Support &amp;amp; Deal Structuring:&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;335557856&amp;quot;:16777215,&amp;quot;335559685&amp;quot;:0,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:0}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li style=&quot;font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Partner with Account teams and Network commercial teams to develop compelling and competitive pricing proposals for new and existing clients.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;335557856&amp;quot;:16777215,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:0}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Serve as the point of contact and subject matter expert on deal constructs, special pricing, and ad hoc troubleshooting of deal issues and sales escalations.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;335557856&amp;quot;:16777215,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:0}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Negotiate pricing and contractual terms with clients.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;335557856&amp;quot;:16777215,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:0}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Provide quick and accurate responses to client teams inquiries regarding WPP Open pricing.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;335557856&amp;quot;:16777215,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:0}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Develop pricing proposals for individual deals, including WPP Open pilot programs and use cases.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;335557856&amp;quot;:16777215,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:0}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;span style=&quot;font-size: 10pt;&quot; data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;335557856&amp;quot;:16777215,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:0}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Enablement:&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;335557856&amp;quot;:16777215,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:210}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li style=&quot;font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Create and deliver pricing communication materials, including pricing guides, value propositions, and training sessions for internal and external stakeholders.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;335557856&amp;quot;:16777215,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:0}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Effectively communicate pricing changes and updates to relevant parties.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;335557856&amp;quot;:16777215,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:0}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;span style=&quot;font-size: 10pt;&quot; data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;335557856&amp;quot;:16777215,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:0}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Analysis &amp;amp; Reporting:&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;335557856&amp;quot;:16777215,&amp;quot;335559685&amp;quot;:0,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:0}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li style=&quot;font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Conduct quantitative and qualitative analyses using internal (e.g., financials) and external (e.g., benchmarks) sources to support pricing strategy development.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;335557856&amp;quot;:16777215,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:0}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Track and analyse key pricing metrics to monitor performance and identify areas for improvement.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;335557856&amp;quot;:16777215,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:0}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Prepare regular reports on pricing performance and trends&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;335557856&amp;quot;:16777215,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:0}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;span style=&quot;text-decoration: underline; font-size: 10pt;&quot;&gt;&lt;strong&gt;What you&#39;ll need:&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li style=&quot;font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Experience in pricing, commercial strategy, or a related role within the media or advertising industry.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;335557856&amp;quot;:16777215,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:0}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Analytical skills and experience with financial modeling.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;335557856&amp;quot;:16777215,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:0}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Excellent communication and presentation skills, with the ability to explain complex concepts clearly and concisely.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;335557856&amp;quot;:16777215,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:0}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Proven ability to collaborate effectively with cross-functional teams.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;335557856&amp;quot;:16777215,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:0}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Negotiation and influencing skills.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;335557856&amp;quot;:16777215,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:0}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Proficient in Microsoft Excel and other relevant software (e.g., pricing optimisation tools, CRM systems).&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;335557856&amp;quot;:16777215,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:0}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Agility and flexibility, along with project management skills.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;335557856&amp;quot;:16777215,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:0}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Experience with programmatic pricing models and platforms is a plus.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;335557856&amp;quot;:16777215,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:0}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Desired Skills:&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;335557856&amp;quot;:16777215,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:210}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li style=&quot;font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Experience with pricing software and tools.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;335557856&amp;quot;:16777215,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:0}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Knowledge of the WPP network and its agencies.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;335557856&amp;quot;:16777215,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:0}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Understanding of different media buying models (e.g., CPM, CPC, CPA) is essential.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;335557856&amp;quot;:16777215,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:0}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;span style=&quot;color: rgb(236, 240, 241); font-size: 10pt;&quot;&gt;#LI-Hybrid&amp;nbsp;&lt;/span&gt;&lt;/p&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;p&gt;&lt;strong&gt;We believe the best work happens when we&#39;re together, fostering creativity, collaboration, and connection. That&#39;s why we’ve adopted a hybrid approach, with teams in the office around four days a week. If you require accommodations or flexibility, please discuss this with the hiring team during the interview process.&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;WPP is an equal opportunity employer and considers applicants for all positions without discrimination or regard to particular characteristics. We are committed to fostering a culture of respect in which everyone feels they belong and has the same opportunities to progress in their careers.&lt;/strong&gt;&lt;/p&gt;
&lt;h4&gt;&lt;strong&gt;Please read our Privacy Notice (&lt;a href=&quot;https://www.wpp.com/en/careers/wpp-privacy-policy-for-recruitment&quot;&gt;https://www.wpp.com/en/careers/wpp-privacy-policy-for-recruitment&lt;/a&gt;) for more information on how we process the information you provide.&lt;/strong&gt;&lt;/h4&gt;&lt;/div&gt;<p>Find <a href="https://www.arbeitnow.co.uk">Jobs in United Kingdom</a> on Arbeitnow</a>

&lt;div class=&quot;content-intro&quot;&gt;&lt;p&gt;&lt;strong&gt;WPP is the trusted growth partner for the world’s leading brands.&amp;nbsp;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;We unite cutting-edge media intelligence and data solutions, world-class creativity, next-generation production, transformative enterprise solutions and expert strategic counsel in a single company – powered by exceptional talent and our agentic marketing platform, WPP Open, to help our clients navigate change, capture opportunity and deliver transformational growth.&amp;nbsp;&lt;/strong&gt;&lt;br&gt;&lt;strong&gt;&amp;nbsp;&lt;/strong&gt;&lt;br&gt;&lt;strong&gt;We work with the world&#39;s most valuable brands and have global reach across 100+ markets, with deep local expertise.&lt;/strong&gt;&lt;br&gt;&lt;strong&gt;&amp;nbsp;&lt;/strong&gt;&lt;br&gt;&lt;strong&gt;Our people are the key to our success. We&#39;re committed to fostering a culture of creativity, belonging and continuous learning, attracting and developing the brightest talent, and providing exciting career opportunities that help our people grow.&amp;nbsp;&lt;/strong&gt;&lt;br&gt;&lt;strong&gt;&amp;nbsp;&lt;/strong&gt;&lt;br&gt;&lt;strong&gt;For more information, visit &lt;a href=&quot;https://eur02.safelinks.protection.outlook.com/?url=http%3A%2F%2Fwpp.com%2F&amp;amp;data=05%7C02%7CErica.Durr%40wpp.com%7C9bf4566a65bc46a48ac008de749116ea%7C150b5e663d884dee83f6ed149b727a00%7C0%7C0%7C639076363668176216%7CUnknown%7CTWFpbGZsb3d8eyJFbXB0eU1hcGkiOnRydWUsIlYiOiIwLjAuMDAwMCIsIlAiOiJXaW4zMiIsIkFOIjoiTWFpbCIsIldUIjoyfQ%3D%3D%7C0%7C%7C%7C&amp;amp;sdata=Q9juosud56XGLThSFZ1NpPZd6FXpJPxV74OeRZWoh%2B4%3D&amp;amp;reserved=0&quot; target=&quot;_blank&quot;&gt;WPP.com.&lt;/a&gt;&lt;/strong&gt;&lt;br&gt;&lt;strong&gt;&amp;nbsp;&lt;/strong&gt;&lt;/p&gt;&lt;/div&gt;&lt;p&gt;&lt;span style=&quot;text-decoration: underline;&quot;&gt;&lt;strong&gt;Why we&#39;re hiring:&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span class=&quot;TextRun SCXW1676860 BCX0&quot; lang=&quot;EN-GB&quot; data-contrast=&quot;auto&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW1676860 BCX0&quot;&gt;As part of WPPs Elevate28 strategy,&amp;nbsp;&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW1676860 BCX0&quot;&gt;we are accelerating a major Finance Technology transformation to simplify, modernise and standardise the platforms, data and processes that underpin &lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW1676860 BCX0&quot;&gt;G&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW1676860 BCX0&quot;&gt;lobal&amp;nbsp;&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW1676860 BCX0&quot;&gt;F&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW1676860 BCX0&quot;&gt;inance. This portfolio is critical to statutory reporting, management reporting, forecasting, planning, control, performance management&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW1676860 BCX0&quot;&gt;, compliance,&lt;/span&gt;&lt;span class=&quot;NormalTextRun SCXW1676860 BCX0&quot;&gt;&amp;nbsp;and executive decision-making.&lt;/span&gt;&lt;/span&gt;&lt;span class=&quot;EOP Selected SCXW1676860 BCX0&quot; data-ccp-props=&quot;{&amp;quot;335559739&amp;quot;:120}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;The&amp;nbsp;&lt;strong&gt;Global Programme Director - Finance Technology&lt;/strong&gt; will shape, govern and drive WPP’s global Finance Technology transformation portfolio. This senior enterprise leadership role turns a complex, multi-year agenda into a coherent roadmap that simplifies the finance technology estate, strengthens control and resilience, and enables faster, more trusted business insight.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559739&amp;quot;:120}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;The role spans Finance ERP standardisation, consolidation platform replacement, enterprise performance management, revenue forecasting, analytics, finance data&amp;nbsp;foundations&amp;nbsp;and operating model change. It will work across Group Finance, Enterprise Technology, agencies, markets,&amp;nbsp;regions&amp;nbsp;and delivery partners to align priorities, secure decisions, manage trade-offs and ensure investment delivers measurable enterprise value.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559739&amp;quot;:120}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;This is a director-level role requiring strategic judgement, executive influence, commercial&amp;nbsp;discipline&amp;nbsp;and the ability to create clarity,&amp;nbsp;momentum&amp;nbsp;and delivery confidence across a high-profile transformation portfolio.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559739&amp;quot;:120}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span style=&quot;text-decoration: underline;&quot;&gt;&lt;strong&gt;What you&#39;ll be doing:&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;16&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Shape and sequence the global Finance ERP roadmap, moving WPP towards fewer platforms, common templates, harmonised controls and reduced process variation&lt;/span&gt;&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;16&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;Lead the transition from legacy consolidation tooling to a resilient enterprise performance management capability across consolidation, planning, forecasting, reporting and analytics&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;16&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;Strengthen delivery confidence, investment discipline and benefits realisation across a high-value portfolio with significant executive visibility and business risk&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;16&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;Define the global Finance Technology portfolio vision, investment narrative and multi-year roadmap across Finance ERP, consolidation, enterprise performance management, forecasting, analytics and finance data&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;16&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;Translate finance transformation priorities into a clear, sequenced and deliverable portfolio that balances strategic value, delivery capacity, affordability, risk and business disruption&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;16&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;Establish strong portfolio governance, investment controls, stage gates, assurance and executive reporting to support timely, evidence-based decisions&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;16&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;Lead and orchestrate a portfolio of finance transformation programmes, ensuring clear sponsorship, ownership, outcomes, funding, delivery accountability and benefits realisation&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;16&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;Manage portfolio risks, dependencies, resources, budgets, delivery confidence and executive escalations across Finance, Enterprise Technology, data, architecture, security, controls, suppliers, markets and agencies&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;16&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;Build trusted relationships with senior Finance, Enterprise Technology, agency, market and regional leaders to align priorities, resolve trade-offs and maintain enterprise momentum&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;16&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;Shape business cases, funding recommendations and portfolio choices using clear analysis of cost, benefit, risk, sequencing, control impact and business value&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;16&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;Manage system integrators, software vendors and delivery partners against commitments, outcomes, commercial levers and performance expectations&lt;/li&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;16&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;multilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;Lead and coach programme directors, delivery leads, PMOs and matrixed teams to raise delivery standards, strengthen transparency and build a culture of accountability.&lt;span data-ccp-props=&quot;{&amp;quot;134233279&amp;quot;:false}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;span style=&quot;text-decoration: underline;&quot;&gt;&lt;strong&gt;What you&#39;ll need:&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
