&lt;li data-renderer-start-pos=&quot;8919&quot; data-local-id=&quot;78ee56f2-dd8a-4b86-9336-f5666110b0fc&quot;&gt;Sales training in &lt;span data-highlighted=&quot;true&quot; data-vc=&quot;highlighted-text&quot;&gt;&lt;span class=&quot;_kqswh2mm&quot;&gt;&lt;span class=&quot;_5pioz8co _189e1dm9 _1il9buyh _19lc184f _d0altlke&quot; data-testid=&quot;definition-highlighter&quot;&gt;MEDDIC&lt;/span&gt;&lt;/span&gt;&lt;/span&gt; and Command of the Message&lt;/li&gt;
