&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Sicherstellung&amp;nbsp;von&amp;nbsp;Qualitäts-,&amp;nbsp;Sicherheits- und Compliance-Anforderungen&amp;nbsp;innerhalb&amp;nbsp;der Supply Chain&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335551550&amp;quot;:1,&amp;quot;335551620&amp;quot;:1,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:300}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
