&lt;p&gt;&lt;strong&gt;&lt;br&gt;Wir bieten dir&lt;/strong&gt;&lt;strong&gt;&amp;nbsp;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Raum&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt; &lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;für Vielfalt und Raum für Innovation.&lt;br&gt;&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Möglichkeiten für deine Ideen.&amp;nbsp;&lt;/span&gt;&lt;br&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Rabatt auf viele Produkte der Sony Corporation.&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt; &lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt; &lt;/span&gt;&amp;nbsp;&lt;br&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Die Chance, dich zu beweisen. Und Herausforderung von Anfang an.&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt; &lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt; &lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;134233118&amp;quot;:true,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;br&gt;&lt;/span&gt;&lt;/p&gt;
